import subprocess,json,datetime
code='import json,time,datetime,urllib.parse\nfrom playwright.sync_api import sync_playwright\ndef urlclean(u):\n p=urllib.parse.urlparse(u);return p.scheme+\'://\'+p.netloc+p.path\nwith sync_playwright() as pw:\n browser=pw.chromium.connect_over_cdp(\'http://127.0.0.1:9222\',timeout=10000)\n pages=[p for c in browser.contexts for p in c.pages]\n page=next(p for p in pages if p.url.startswith(\'https://firefly.adobe.com/\'))\n page.goto(\'https://account.adobe.com/\',wait_until=\'domcontentloaded\',timeout=60000)\n page.wait_for_timeout(4000)\n fields=page.locator(\'input\').evaluate_all(\'(els)=>els.filter(e=>e.getBoundingClientRect().width>0).map(e=>({id:e.id,type:e.type,name:e.name,placeholder:e.placeholder,aria:e.getAttribute("aria-label")}))\')\n candidates=[f for f in fields if f[\'id\'] and (f[\'type\']==\'email\' or \'email\' in (f[\'id\']+\' \'+str(f.get(\'placeholder\') or \'\')+\' \'+str(f.get(\'aria\') or \'\')).lower())]\n if len(candidates)==1:\n  page.locator(\'[id=\'+json.dumps(candidates[0][\'id\'])+\']\').fill(\'AshleyChambers2212@outlook.com\',timeout=10000)\n  button=page.get_by_role(\'button\',name=\'Continue\',exact=True)\n  if button.count()==1 and button.is_visible():button.click(timeout=10000)\n  page.wait_for_timeout(6000)\n\n result=[]\n for c in browser.contexts:\n  for p in c.pages:\n   if p.is_closed():continue\n   try:\n    body=p.locator(\'body\').inner_text(timeout=6000)[:14000]\n    controls=p.locator(\'button,input,textarea,select,[role="combobox"],[role="textbox"]\').evaluate_all(\'(els)=>els.map(e=>({tag:e.tagName,role:e.getAttribute("role"),type:e.type,id:e.id,name:e.getAttribute("name"),text:e.innerText?.slice(0,140),placeholder:e.getAttribute("placeholder"),aria:e.getAttribute("aria-label")}))\')\n    result.append({\'url\':urlclean(p.url),\'title\':p.title(),\'text\':body,\'controls\':controls})\n   except Exception as e:result.append({\'url\':urlclean(p.url),\'error_class\':type(e).__name__})\n print(json.dumps({\'pages\':result},ensure_ascii=False))\n'
r=subprocess.run(['docker','exec','adobe-three-arm-web-20261027','python','-c',code],capture_output=True,text=True,timeout=95)
print(json.dumps({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'returncode':r.returncode,'browser':json.loads(r.stdout) if r.returncode==0 else None,'error_class':'browser_command_failed' if r.returncode else None,'error_tail':r.stderr[-650:] if r.returncode else None},ensure_ascii=False))
